// Playlist: https://www.shadertoy.com/playlist/mfdGWj

// Recreating some illustrations from Eric Lengyel's "Projective Geometric Algebra Illuminated".

// between two vec2's, the wedge product returns area of a parallelogram
float wedge(vec2 a, vec2 b) {
    return (a.x*b.y - a.y*b.x);    
}

struct bivec3 {
    vec3 v;
    vec3 m;
};

bivec3 lineToBivector(vec4 p, vec4 q) {
    bivec3 l;
    l.v.x = wedge(p.wx, q.wx);
    l.v.y = wedge(p.wy, q.wy);
    l.v.z = wedge(p.wz, q.wz);
    l.m.x = wedge(p.yz, q.yz);
    l.m.y = wedge(p.zx, q.zx);
    l.m.z = wedge(p.xy, q.xy);
    return l;
}

bivec3 unitizeLine(bivec3 l) {
    float lenV = length(l.v);
    l.m /= lenV;
    l.v /= lenV;
    return l;
}

// Returns the crossing orientation of lines l and k.
// If positive, then the direction of each line is wound clockwise around the other.
// If negative, then the winding is counterclockwise.
float meetLineLine(bivec3 l, bivec3 k)
{
    #if 0
    // deriving from the antiwedge (exterior) antiproduct table...
    //  https://rigidgeometricalgebra.org/wiki/index.php?title=Exterior_products
    // e41 ∨ e23 := -1, e42 ∨ e31 := -1, e43 ∨ e12 := -1, 
    // e23 ∨ e41 := -1, e31 ∨ e42 := -1, e12 ∨ e43 := -1,

    // So, the antiwedge product between two lines is given by:
    // l∨k = -l.v.x*k.m.x + -l.v.y*k.m.y + -l.v.z*k.m.z 
    //     + -l.m.x*k.v.x + -l.m.y*k.v.y + -l.m.z*k.v.z;
    return -l.v.x*k.m.x - l.v.y*k.m.y -l.v.z*k.m.z - l.m.x*k.v.x - l.m.y*k.v.y - l.m.z*k.v.z;
    #else
    // which we can also write as an expression consisting of two dot products.
    return -dot(l.v, k.m) -dot(l.m, k.v);
    #endif
}

// Does not require lines to be unitized. 
float distLineLine(bivec3 l, bivec3 k, float lmeetk) {
    return abs(lmeetk) / length(cross(l.v, k.v));
}

// Assuming lines are unitized.
void closestPtsBetweenLines(bivec3 l, bivec3 k, float meet, out vec3 pL, out vec3 pK) {
    // Hard to get around these two cross products with plucker coordinates. 
    // Arguably more efficient to stick with o + t*d version...
    vec3 p0_l = cross(l.v, l.m);
    vec3 p0_k = cross(k.v, k.m);
    float c    = dot(l.v, k.v);
    float denom = 1.0 - c * c;         // = |l.v × k.v|^2
    vec3 r = p0_k - p0_l;

    // Expand cross(r, k.v) dot (l.v × k.v) using vector triple products:
    vec3 vk_vlkv = l.v - c * k.v;    // cross(k.v, cross(l.v, k.v))
    vec3 lv_lvkv = c * l.v - k.v;    // cross(l.v, cross(l.v, k.v))

    float t = dot(r, vk_vlkv) / denom;
    float u = dot(r, lv_lvkv) / denom;

    pL = p0_l + t * l.v;
    pK = p0_k + u * k.v;
}

