#define OUTLINE_WIDTH .01

#define M2PI 6.28318530718

#if HW_PERFORMANCE==0
#define AA 1
#else
#define AA 2   // make this 2 or 3 for antialiasing
#endif

struct Payload {
    float d; // distance
    vec3 albedo; // albedo
};

const float lineThickness = .005;
const float arrowThickness = .04;
const float arrowCapWidth = .1;
const float arrowCapHeight = .2;

const float xLength = 2.0;
const float yLength = 2.0;
const float wLength = 2.0;
const float wPlaneHeight = 1.0;

void getLLine(out vec4 p, out vec4 q) {
    p = vec4(0.0, 0.0, wPlaneHeight*0.5, 1.0);
    q = vec4(0.0, 0.0, wPlaneHeight*1.0, 1.0);

    q.xyz *= 2.0;
    p.xyz -= normalize(q.xyz - p.xyz);
}

void getKLine(out vec4 p, out vec4 q) {
    p = vec4(cos(iTime*.5)*1.5, cos(iTime*.2)* 1.6, wPlaneHeight*.75 + sin(iTime*.7)*.3, 1.0);
    q = vec4(cos(iTime*.5)*1.5, sin(iTime*.2)* -1.6, wPlaneHeight*.75 + sin(iTime*.5)*.3, 1.0);    
}


const vec3 white = vec3(255.)/255.;
const vec3 green = vec3(118., 185.,0.)/255.;
const vec3 emerald = vec3(0.,133.,100.)/255.;
const vec3 blue = vec3(0.,113.,197.)/255.;
const vec3 purple = vec3(93.,22.,130.)/255.;


float sdTorusXY( vec3 p, vec2 t )
{
    return length( vec2(length(p.xy)-t.x,p.z) )-t.y;
}


float sdCapsule( vec3 p, vec3 a, vec3 b, float r )
{
	vec3 pa = p-a, ba = b-a;
	float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
	return length( pa - ba*h ) - r;
}

//https://www.shadertoy.com/view/NttcW8
float sdArrow(vec3 position, vec3 start, vec3 end, float baseRadius, float tipRadius, float tipHeight) {
    vec3 t = start - end;
    float l = length(t);
    t /= l;
    l = max(l, tipHeight);

    position -= end;
    if (t.y + 1.0 < 0.0001) {
        position.y = -position.y;
    } else {
        float k = 1.0 / (1.0 + t.y);
        vec3 column1 = vec3(t.z * t.z * k + t.y, t.x, t.z * -t.x * k);
        vec3 column2 = vec3(-t.x, t.y, -t.z);
        vec3 column3 = vec3(-t.x * t.z * k, t.z, t.x * t.x * k + t.y);
        position = mat3(column1, column2, column3) * position;
    }

    vec2 q = vec2(length(position.xz), position.y);
    q.x = abs(q.x);

    // tip
    vec2 e = vec2(tipRadius, tipHeight);
    float h = clamp(dot(q, e) / dot(e, e), 0.0, 1.0);
    vec2 d1 = q - e * h;
    vec2 d2 = q - vec2(tipRadius, tipHeight);
    d2.x -= clamp(d2.x, baseRadius - tipRadius, 0.0);

    // base
    vec2 d3 = q - vec2(baseRadius, tipHeight);
    d3.y -= clamp(d3.y, 0.0, l - tipHeight);
    vec2 d4 = vec2(q.y - l, max(q.x - baseRadius, 0.0));

    float s = max(max(max(d1.x, -d1.y), d4.x), min(d2.y, d3.x));
    return sqrt(min(min(min(dot(d1, d1), dot(d2, d2)), dot(d3, d3)), dot(d4, d4))) * sign(s);
}


Payload map(in vec3 ro, vec3 rd) {
    Payload res;
    res.d = 1e38f;
    res.albedo = vec3(0.0);

    // Line L
    vec4 lp, lq;
    getLLine(lp, lq);    
    bivec3 l = lineToBivector(lp, lq);

    // Line K
    vec4 kp, kq;
    getKLine(kp, kq);    
    bivec3 k = lineToBivector(kp, kq);

    // Compute the meet of L and K
    float mlk = meetLineLine(l, k);    

    // Compute the distance beteen L and K
    float dist = distLineLine(l, k, mlk);

    // Visualize line L
    {
        vec3 start = lp.xyz / lp.w;
        vec3 stop = lq.xyz / lq.w;
        float d1 = sdArrow(ro, start, stop, arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
        if (d1 < res.d) {res.d = d1; res.albedo = green;}

        vec3 dir = normalize(stop - start);
        float d2 = sdCapsule(ro, start - 4.0*dir, stop + 4.0*dir, 0.0);

        float d2Start = distance(ro, start);
        float d2Stop = distance(ro, stop);

        if (d2 < res.d) {res.d = d2; res.albedo = mix(white, green, exp( -1.5*length( min(d2Stop, d2Start) )) ) ;}
    }

    // Visualize line K
    {
        vec3 start = kp.xyz / kp.w;
        vec3 stop = kq.xyz / kq.w;
        float d = sdArrow(ro, start, stop, arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
        if (d < res.d) {res.d = d; res.albedo = emerald;}

        vec3 dir = normalize(stop - start);
        float d2 = sdCapsule(ro, start - 4.0*dir, stop + 4.0*dir, 0.0);

        float d2Start = distance(ro, start);
        float d2Stop = distance(ro, stop);

        if (d2 < res.d) {res.d = d2; res.albedo = mix(white, emerald, exp( -1.5*length( min(d2Stop, d2Start) )) ) ;}
    }


    // Visualize the meet of L and K with a circle. 
    // When the meet of the lines is negative, the circle will go purple, indicating 
    // a counterclockwise winding order. Otherwise, the circle will appear blue, indicating a clockwise orientation.
    {
        float sigmoid = 1.f / (1.f + exp(-mlk));        
        vec3 color = mix(purple, blue, sigmoid);

        // Visualize the distance between the two lines using the radius of a torus
        float torusRadius = dist;

        // Unitize the two lines before computing where they meet =.
        l = unitizeLine(l);
        k = unitizeLine(k);
        vec3 pl, pk;
        closestPtsBetweenLines(l, k, mlk, pl, pk);

        float d1 = sdCapsule( ro, pl, pk, lineThickness );
        if (d1 < res.d) {res.d = d1; res.albedo = mix(color, white, (cos(distance(ro, pk)*30.)*.5+.5));}

        float d = sdTorusXY( ro - pl, vec2(torusRadius, .01) );
        if (d < res.d) {res.d = d; res.albedo = color;}

        // Visualize the winding order around the torus
        float s = sign(mlk);
        float t0 = iTime * s;
        float t1 = iTime * s + .1* s;
        vec3 pt1OnTorus = vec3(sin(t0), cos(t0), 0.0) * torusRadius;
        vec3 pt2OnTorus = vec3(sin(t1), cos(t1), 0.0) * torusRadius;

        float d3 = sdArrow(ro, pt1OnTorus + pl, pt2OnTorus + pl, arrowThickness, arrowCapWidth, arrowCapHeight*1.1);
        if (d3 < res.d) {res.d = d3; res.albedo = color;}
    }

    return res;
}

vec4 over(vec4 a, vec4 b) {
  vec4 result;
  result.a = a.a + b.a * (1.f - a.a);
  if (result.a == 0.f)
    return a;   // avoid NaN
  result.rgb = (a.rgb * a.a + b.rgb * b.a * (1.f - a.a)) / result.a;
  return result;
}

vec3 scene(in vec3 ro,in vec3 rd) {
    vec3 col = vec3(1.0);		// initialize color return value

    vec3 roStart = ro;

    #define NHITS 2
    vec4 tuvs[NHITS];

    tuvs[0].x = 1e38f;

    for (int i = 0; i < NHITS; ++i) tuvs[i].xw = vec2(1e38f, i);

    Payload payload;

    float rm = 1e38f; 			// tracker for minimum ray value
    float tmin = 10.0;
    float tmax = 25.0;
    float t = tmin;
    ro = roStart + t * rd;

    float ow = OUTLINE_WIDTH; 		// outline width
    for (int i =0; i<50; i++) {
        payload = map(ro, rd);
        rm = min(payload.d, rm);

        //check if a ray has passed through an outline region
        if (payload.d > rm && rm < ow * 2.5){
            col = vec3(0); //outline
            break;
        }

        if (payload.d < ow) {
            //color based on suface location
            col = payload.albedo;
            break;
        }

        t += payload.d * .9;
       	ro = roStart + t * rd;//*0.85;
        if (t > tmax) break;
    }

    tuvs[NHITS-1].x = t;

    vec4 bgcol = vec4(col, 1.0);

    // Sort by hit depth
    for (int i = 0; i < NHITS-1; ++i) {
        for (int j = 0; j < NHITS-1; ++j) {
            if (tuvs[j].x < tuvs[j+1].x) {
                vec4 tmp = tuvs[j];
                tuvs[j] = tuvs[j+1];
                tuvs[j+1] = tmp;
            }
        }
    }

    // Composite the W=1 plane
    vec4 rgba = vec4(1.0, 1.0, 1.0, .0);
    for (int i = 0; i < NHITS; ++i) {
        if( tuvs[i].x>0.0)
        {
            vec4 geoCol;
            if (tuvs[i].w == 0.0) geoCol = vec4(green, .8);
            else if (tuvs[i].w == float(NHITS-1)) geoCol = vec4(col, 1.0);
            else geoCol = vec4(green, .7);            
            rgba = over(geoCol, rgba);
        }
    }

    return rgba.rgb;
}

mat3 lookAt(in vec3 eye, in vec3 tar, in float r){
    vec3 cw = normalize(tar - eye);// camera w
    vec3 cp = vec3(sin(r), 0., cos(r));// camera up
    vec3 cu = normalize(cross(cw, cp));// camera u
    vec3 cv = normalize(cross(cu, cw));// camera v
    return mat3(cu, cv, cw);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 tot = vec3(0.0);

    // camera
    float an = .2;//-0.05*iTime -5.0*iMouse.x/iResolution.x;

    float dist = 20.f;
    float fov = 5.f;    

    vec3  ro = dist * vec3(cos(3.0*an),sin(3.0*an), .3);
    vec3  ta = vec3(0.0,0.0,4./6.0);

    // camera matrix
    vec3 ww = normalize( ta - ro );
    vec3 uu = normalize( cross(ww,vec3(0.0,0.0,1.0) ) );
    vec3 vv = normalize( cross(uu,ww));

    for( int m=0; m<AA; m++ )
    for( int n=0; n<AA; n++ )
    {           
        //create p for ray based on AA settings
        vec3 p = vec3((-iResolution.xy + 2.0*(fragCoord.xy-0.5+(vec2(float(m),float(n))+0.5)/float(AA))) / iResolution.y,2.0);


        //create view ray from vector p
        vec3 rd = lookAt(ro, ta, 0.)*normalize(vec3(p.xy, 1.0/radians(fov)));// ray direction

        //render scene
        vec3 col = scene(ro,rd);

        tot += col;
    }
    tot /= float(AA*AA);
    fragColor = vec4( tot, 1.0 );
}
